use retail_dataset;

SELECT * FROM customer_data_data;

#Q1. What is the total revenue generated by gender?

select gender, SUM(purchase_amount_usd_usd) as revenue
from customer_data_data
group by gender;

#Which customer_datas used a discount ,spent more than the average purchase amount? 
select customer_id, purchase_amount_usd 
from customer_data 
where discount_applied = 'Yes' and purchase_amount_usd >= (select AVG(purchase_amount_usd) from customer_data);


#Q3 Top 5 products with highest avg review rating
select item_purchased, round(avg(review_rating),2) as "Average Product Rating"
from customer_data
group by item_purchased
order by avg(review_rating) desc
limit 5;

#Q4. the average Purchase Amounts between Standard and Express 
select shipping_type, 
ROUND(AVG(purchase_amount_usd),2)
from customer_data
where shipping_type in ('Standard','Express')
group by shipping_type;


#Q5. top 10 products with the highest % of purchases with discounts.
SELECT item_purchased,
       ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 10;

 # The top 3 most purchased products in each category
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer_data
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;



#Q customer_datas who are repeat buyers (more than 5 previous purchases) most to likely to subscribe
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer_data
WHERE previous_purchases > 5
GROUP BY subscription_status;

#Q revenue contribution acc to age group 
SELECT 
    age_bracket,
    SUM(purchase_amount_usd) AS total_revenue
FROM customer_data
GROUP BY age_bracket
ORDER BY total_revenue desc;
